let weatherForm=document.querySelector("#weatherForm"),city=weatherForm.querySelector('input[name="city"]'),btn=weatherForm.querySelector('button[name="submit-button"]'),weatherContainer=document.querySelector("#weather-data"),API_KEY="8967388ef15aab5dc6624ae602ea61c9";function renderWeather(e){weatherContainer.classList.remove("hidden"),console.log(e),weatherContainer.querySelector("#weather-city").innerText=e.name,weatherContainer.querySelector("#weather-description").innerText=e.weather[0].description,weatherContainer.querySelector("#weather-temperature").innerText=`Температура: ${Math.round(e.main.temp)}°C`,weatherContainer.querySelector("#weather-feels-like").innerText=`Відчувається як: ${Math.round(e.main.feels_like)}°C`,weatherContainer.querySelector("#weather-humidity").innerText=`Вологість: ${e.main.humidity}%`,weatherContainer.querySelector("#weather-wind").innerText=`Вітер: ${e.wind.speed} м/с`,weatherContainer.querySelector("#weather-icon").setAttribute("src",`https://openweathermap.org/img/wn/${e.weather[0].icon}@2x.png`),weatherContainer.querySelector("#weather-icon").setAttribute("alt",e.weather[0].description)}weatherForm.addEventListener("submit",async e=>{e.preventDefault();e=city.value.trim();if(e)try{var t=await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${e}&appid=${API_KEY}&units=metric&lang=ua`),r=await t.json();if(!t.ok)throw new Error(r.message||"City not found");renderWeather(r)}catch(e){console.error(e),alert(e.message)}else alert("Enter city name")});